 return(x);
}
unsigned int SEED = 1;
unsigned int TIME = 1;
void srand(unsigned int seed) {
 SEED = seed;
 TIME = 1;
}
int rand(void) {
 SEED += TIME;
 if(SEED != RAND_MAX) {
  while(SEED < RAND_MAX)
   SEED *= SEED + 1;
  while(SEED >= RAND_MAX)
   SEED -= RAND_MAX;
 }
 TIME++;
 return((int)SEED);
}

